INSERT INTO public.real_english_expressions
  (id, slug, kind, expression, meaning_vi, context_explanation, example_en, example_vi,
   dialogue, formality, region_note, source_name, license_id, provenance_note, is_published)
VALUES
('22222222-2222-4222-8222-222222222201','no-biggie','slang','No biggie','Không có gì to tát','Use this to reassure someone about a small inconvenience. Avoid it in formal apologies.','I can resend the file. No biggie.','Tôi có thể gửi lại tệp. Không có gì to tát.','[{"speaker":"Mia","line":"Sorry, I left the notes at home."},{"speaker":"Leo","line":"No biggie. We can use mine."}]','informal','Common in American English; understood more widely.','Englify Quest editorial','project-original','Original educational example and dialogue written for this project.',true),
('22222222-2222-4222-8222-222222222202','break-the-ice','idiom','Break the ice','Phá vỡ sự ngại ngùng ban đầu','Use this when an activity helps people feel comfortable at the start of a meeting.','A quick game helped us break the ice.','Một trò chơi ngắn giúp chúng tôi bớt ngại ngùng.','[{"speaker":"An","line":"Everyone seems nervous."},{"speaker":"Sam","line":"Let’s ask a fun question to break the ice."}]','neutral','Widely used across English-speaking regions.','Englify Quest editorial','project-original','Original educational example and dialogue written for this project.',true),
('22222222-2222-4222-8222-222222222203','figure-out','phrasal_verb','Figure out','Tìm ra; hiểu ra','Use this for solving a problem or understanding something after thinking.','We figured out how to reach the station.','Chúng tôi đã tìm ra cách đến nhà ga.','[{"speaker":"Nora","line":"Which bus goes downtown?"},{"speaker":"Kai","line":"Let’s figure it out on the map."}]','neutral','Common in American and British English.','Englify Quest editorial','project-original','Original educational example and dialogue written for this project.',true),
('22222222-2222-4222-8222-222222222204','sounds-good','casual_expression','Sounds good','Nghe ổn đấy','Use this to agree with a suggestion in a friendly conversation. It does not promise detailed approval.','Meet at six? Sounds good.','Gặp lúc sáu giờ nhé? Nghe ổn đấy.','[{"speaker":"Ari","line":"Shall we study after lunch?"},{"speaker":"Jo","line":"Sounds good. I’ll bring my notes."}]','informal','Widely understood; tone depends on context.','Englify Quest editorial','project-original','Original educational example and dialogue written for this project.',true),
('22222222-2222-4222-8222-222222222205','could-i-get','everyday_conversation','Could I get a tea, please?','Cho tôi một tách trà được không?','A polite request when ordering. Could I have is also natural in many regions.','Could I get a tea, please?','Cho tôi một tách trà được không?','[{"speaker":"Customer","line":"Could I get a tea, please?"},{"speaker":"Barista","line":"Of course. Hot or iced?"}]','neutral','Could I get is especially common in North America.','Englify Quest editorial','project-original','Original café exchange written for this project.',true),
('22222222-2222-4222-8222-222222222206','last-train-scene','movie_style_dialogue','We still have one chance.','Chúng ta vẫn còn một cơ hội.','A dramatic but original line for discussing hope and urgency. This is not a quote from a film.','We still have one chance to catch the last train.','Chúng ta vẫn còn một cơ hội bắt chuyến tàu cuối.','[{"speaker":"Linh","line":"The station closes in ten minutes."},{"speaker":"Noah","line":"We still have one chance. Take the shortcut with me."}]','neutral','Original fictional scene; no specific regional usage.','Englify Quest editorial','project-original','Original film-style scene written for this project; no film adaptation or media.',true)
ON CONFLICT (slug) DO UPDATE SET
  kind=EXCLUDED.kind, expression=EXCLUDED.expression, meaning_vi=EXCLUDED.meaning_vi,
  context_explanation=EXCLUDED.context_explanation, example_en=EXCLUDED.example_en,
