  is_published=EXCLUDED.is_published, updated_at=now();

INSERT INTO public.real_english_quiz_questions
  (id, expression_id, prompt, options, answer_id, explanation)
VALUES
('33333333-3333-4333-8333-333333333301','22222222-2222-4222-8222-222222222201','A friend apologizes for being two minutes late. Which reply sounds relaxed?','[{"id":"a","text":"No biggie. We can start now."},{"id":"b","text":"This is a grave breach of contract."},{"id":"c","text":"I have no idea where you are."}]','a','No biggie reassures someone that a small delay is not serious.'),
('33333333-3333-4333-8333-333333333302','22222222-2222-4222-8222-222222222202','A new class is quiet. What could help students break the ice?','[{"id":"a","text":"A short introduction game."},{"id":"b","text":"Ending class immediately."},{"id":"c","text":"Turning off every light."}]','a','A friendly introduction activity helps people feel comfortable.'),
('33333333-3333-4333-8333-333333333303','22222222-2222-4222-8222-222222222203','You do not know the bus route yet. What should you do?','[{"id":"a","text":"Figure it out using the map."},{"id":"b","text":"Figure it up using the map."},{"id":"c","text":"Figure it over using the map."}]','a','Figure out means discover or understand the answer.'),
('33333333-3333-4333-8333-333333333304','22222222-2222-4222-8222-222222222204','Your friend suggests studying at six. You agree. What can you say?','[{"id":"a","text":"Sounds good."},{"id":"b","text":"Sounds impossible to hear."},{"id":"c","text":"Sounds legally binding."}]','a','Sounds good is a friendly way to accept a suggestion.'),
('33333333-3333-4333-8333-333333333305','22222222-2222-4222-8222-222222222205','You are at a café. Which request is polite and natural?','[{"id":"a","text":"Could I get a tea, please?"},{"id":"b","text":"Tea. Now."},{"id":"c","text":"Give tea without asking."}]','a','Could I get ... please? is a natural polite request.'),
('33333333-3333-4333-8333-333333333306','22222222-2222-4222-8222-222222222206','The last train leaves soon. Which line expresses hope despite urgency?','[{"id":"a","text":"We still have one chance."},{"id":"b","text":"We missed every possible chance yesterday."},{"id":"c","text":"The station has no trains."}]','a','The line says a possible opportunity remains.')
ON CONFLICT (expression_id) DO UPDATE SET prompt=EXCLUDED.prompt, options=EXCLUDED.options,
  answer_id=EXCLUDED.answer_id, explanation=EXCLUDED.explanation;
COMMIT;
